#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Security.Cryptography;
using Eldoria.Presentation;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace Eldoria.ReferenceClean.Editor {
public static class ValoriaWorldContactFinishing {
 const string Scene="Assets/Eldoria/ArtTests/ValoriaReferenceClean/Integration/Valoria_City_World_UI.unity";
 static string Ev=>Path.GetFullPath("../docs/evidence/valoria-reference-clean/world-contact222");
 const string Tool="Assets/Eldoria/ArtTests/ValoriaReferenceClean/Integration/Editor/ValoriaWorldContactFinishing.cs";
 [Serializable] public class Acceptance {public bool accepted;public string source_scene_sha256,tool_sha256;public string[] images,hashes;}
 [Serializable] public class Report {public string source_scene_sha256,tool_sha256;public float camera_before,camera_after,urp_shadow_distance,max_viewport_xy_difference,min_apron_before_ground_delta,max_apron_before_ground_delta;public int apron_vertices,retained_props_seated;public bool terrain_and_gameplay_unchanged;}
 [Serializable] public class RoofIndices {public int[] indices;}
 [Serializable] public class RoofSource {public string name,mesh_asset;public Vector3[] local_vertices,world_vertices,normals;public Vector2[] uv,uv2;public RoofIndices[] submeshes;public string[] materials;}
 [Serializable] public class RoofSurvey {public string scene_sha256;public RoofSource[] parts;}
 static void SurveyRoof(string sceneHash){
  var city=Object.FindFirstObjectByType<ValoriaReferenceCleanGameplay>();var parts=new[]{city.BastionOne,city.BastionTwo}.SelectMany(root=>root.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.name=="Bastion_I"||f.name=="Bastion_II").Select(f=>{var m=f.sharedMesh;return new RoofSource{name=f.name,mesh_asset=AssetDatabase.GetAssetPath(m),local_vertices=m.vertices,world_vertices=m.vertices.Select(v=>f.transform.TransformPoint(v)).ToArray(),normals=m.normals.Select(v=>f.transform.TransformDirection(v).normalized).ToArray(),uv=m.uv,uv2=m.uv2,submeshes=Enumerable.Range(0,m.subMeshCount).Select(i=>new RoofIndices{indices=m.GetTriangles(i)}).ToArray(),materials=f.GetComponent<Renderer>().sharedMaterials.Select(x=>AssetDatabase.GetAssetPath(x)).ToArray()};}).ToArray();
  Need(parts.Length==2,"Expected exact integrated Bastion I and II sources");using(var file=File.Create(Ev+"/roof-source-survey.json.gz"))using(var zip=new System.IO.Compression.GZipStream(file,System.IO.Compression.CompressionLevel.Optimal))using(var writer=new StreamWriter(zip)){writer.Write(JsonUtility.ToJson(new RoofSurvey{scene_sha256=sceneHash,parts=parts}));}if(File.Exists(Ev+"/roof-source-survey.json"))File.Delete(Ev+"/roof-source-survey.json");
 }
 [Serializable] public class MeshProof {public Vector3[] before,after;public int[] triangles;}
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static void Need(bool b,string s){if(!b)throw new InvalidOperationException(s);}
 static void Views(ValoriaIntegratedWorld host,string prefix,float distance){
  var c=host.WorldCamera;var pos=c.transform.position;float zoom=c.orthographicSize;
  try{foreach(string id in new[]{"forest-valoria","quarry-valoria","corrupt-scout","engendro-valoria"}){
   var p=host.WorldRoot.GetComponentsInChildren<WorldHotspot>(true).Single(n=>n.Id==id).transform.position;p.y=2;c.transform.position=p-c.transform.forward*distance;
   foreach(float size in new[]{64f,32f,14f}){c.orthographicSize=size;ValoriaReferenceCleanBuilder.Capture(c,Ev+"/"+prefix+"-"+id+"-"+size.ToString("0")+".png",1448,1086);}
   c.orthographicSize=14;ValoriaReferenceCleanBuilder.Capture(c,Ev+"/"+prefix+"-"+id+"-portrait.png",900,1600);
  }}finally{c.transform.position=pos;c.orthographicSize=zoom;}
 }
 public static void Trial(){Run(false);}
 public static void Integrate(){Run(true);}
 static void Run(bool integrate){try{
  Directory.CreateDirectory(Ev);string sourceHash=Hash(Scene);var approved=new Dictionary<string,byte[]>();if(integrate){var a=JsonUtility.FromJson<Acceptance>(File.ReadAllText(Ev+"/accepted-candidate.json"));Need(a.accepted&&a.source_scene_sha256==sourceHash&&a.tool_sha256==Hash(Tool),"Exact accepted world finishing sources required");Need(a.images.Length==16&&a.hashes.Length==16,"All destinations, zooms and portrait required");for(int i=0;i<16;i++){Need(Hash(Ev+"/"+a.images[i])==a.hashes[i],"Reviewed image changed");approved.Add(a.images[i],File.ReadAllBytes(Ev+"/"+a.images[i]));}}
  EditorSceneManager.OpenScene(Scene,OpenSceneMode.Single);SurveyRoof(sourceHash);var host=Object.FindFirstObjectByType<ValoriaIntegratedWorld>();bool active=host.WorldRoot.activeSelf;host.WorldRoot.SetActive(true);var nav=host.WorldNavigation;float oldDistance=nav.cameraDistance;var c=host.WorldCamera;var oldCameraPosition=c.transform.position;var temporary=new List<Object>();var changes=new Dictionary<MeshFilter,Mesh>();var props=new Dictionary<Transform,Vector3>();bool saved=false;
  try{
   Need(Mathf.Abs(oldDistance-350)<.1f,"World source camera no longer matches diagnosed depth");Views(host,"before",oldDistance);
   var all=host.WorldRoot.GetComponentsInChildren<MeshFilter>(true);var ground=all.Single(f=>f.name=="ZoneOne continuous prairie source");var query=ground.gameObject.AddComponent<MeshCollider>();query.sharedMesh=ground.sharedMesh;temporary.Add(query);Physics.SyncTransforms();
   float GroundAt(Vector3 p){Need(query.Raycast(new Ray(new Vector3(p.x,100,p.z),Vector3.down),out var hit,200),"World ground contact query missed");return hit.point.y;}
   var apron=all.Single(f=>f.gameObject.activeInHierarchy&&(f.name.Contains("Connected graded extraction apron")||f.sharedMesh.name.Contains("Connected graded extraction apron")));
   var original=apron.sharedMesh;var before=original.vertices.Select(v=>apron.transform.TransformPoint(v)).ToArray();var vv=before.ToArray();var b=apron.GetComponent<Renderer>().bounds;float minDelta=100,maxDelta=-100;
   for(int i=0;i<vv.Length;i++){var p=vv[i];float groundY=GroundAt(p);minDelta=Mathf.Min(minDelta,p.y-groundY);maxDelta=Mathf.Max(maxDelta,p.y-groundY);float nx=Mathf.Abs((p.x-b.center.x)/Mathf.Max(.1f,b.extents.x)),nz=Mathf.Abs((p.z-b.center.z)/Mathf.Max(.1f,b.extents.z));float edge=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.78f,1,Mathf.Max(nx,nz)));p.y=groundY+Mathf.Lerp(-.025f,.055f,edge)+edge*.025f*Mathf.Sin(p.x*2.1f+p.z*1.7f);vv[i]=p;}
   var mesh=Object.Instantiate(original);mesh.name="Existing quarry extraction apron / measured terrain contact";mesh.vertices=vv.Select(v=>apron.transform.InverseTransformPoint(v)).ToArray();mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();temporary.Add(mesh);changes.Add(apron,original);apron.sharedMesh=mesh;
   File.WriteAllText(Ev+"/apron-contact-source.json",JsonUtility.ToJson(new MeshProof{before=before,after=vv,triangles=mesh.triangles}));
   foreach(var f in all.Where(f=>f.gameObject.activeInHierarchy&&(f.name.StartsWith("Quarry fractured waste")||f.name.StartsWith("Retained functional quarry equipment")))){
    var r=f.GetComponent<Renderer>();if(!r)continue;float delta=GroundAt(r.bounds.center)-r.bounds.min.y+.035f;Need(Mathf.Abs(delta)<4,"Unexpected retained equipment offset");props.Add(f.transform,f.transform.position);f.transform.position+=Vector3.up*delta;
   }
   // Same X/Y projection and existing zoom; only depth moves within the already
   // configured 220-unit shadow range. No URP budget/resolution increase.
   var sample=all.Where(f=>f.gameObject.activeInHierarchy&&f.GetComponent<Renderer>()).Select(f=>f.GetComponent<Renderer>().bounds.center).ToArray();var projected=sample.Select(c.WorldToViewportPoint).ToArray();c.transform.position+=c.transform.forward*(oldDistance-140);float maxError=0;for(int i=0;i<sample.Length;i++){var q=c.WorldToViewportPoint(sample[i]);maxError=Mathf.Max(maxError,Vector2.Distance(new Vector2(q.x,q.y),new Vector2(projected[i].x,projected[i].y)));}Need(maxError<.0001f,"Orthographic framing changed");c.transform.position=oldCameraPosition;nav.cameraDistance=140;
   Views(host,"after",140);Need(Hash(Scene)==sourceHash,"World trial unexpectedly saved scene");var urp=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;Need(urp&&urp.shadowDistance>=200&&urp.shadowDistance<300,"Unexpected URP shadow source");
   var report=new Report{source_scene_sha256=sourceHash,tool_sha256=Hash(Tool),camera_before=oldDistance,camera_after=140,urp_shadow_distance=urp.shadowDistance,max_viewport_xy_difference=maxError,min_apron_before_ground_delta=minDelta,max_apron_before_ground_delta=maxDelta,apron_vertices=mesh.vertexCount,retained_props_seated=props.Count,terrain_and_gameplay_unchanged=true};File.WriteAllText(Ev+"/unity-review.json",JsonUtility.ToJson(report,true));
   if(integrate){var differences=new List<string>();foreach(var a in approved){differences.Add(ValoriaTerrainBankAuthoring.CompareRender(a.Value,Ev+"/"+a.Key));File.WriteAllBytes(Ev+"/approved-"+a.Key,a.Value);}File.WriteAllText(Ev+"/render-identity.json","["+string.Join(",",differences)+"]");const string folder="Assets/Eldoria/ArtTests/ValoriaReferenceClean/Integration/WorldContact222";Need(!Directory.Exists(folder),"Refuse overwrite current world assets");Directory.CreateDirectory(folder);AssetDatabase.Refresh();AssetDatabase.CreateAsset(mesh,folder+"/QuarryApron.asset");Object.DestroyImmediate(query);c.transform.position=oldCameraPosition+c.transform.forward*(oldDistance-140);host.WorldRoot.SetActive(active);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(host.gameObject.scene);Need(EditorSceneManager.SaveScene(host.gameObject.scene,Scene),"World save failed");saved=true;SurveyRoof(Hash(Scene));File.WriteAllText(Ev+"/integrated.json","{\"scene_sha256\":\""+Hash(Scene)+"\",\"gameplay_gate\":\"PENDING_CURRENT_PROBE\",\"published\":false}");}
  }finally{if(!saved){foreach(var kv in changes)kv.Key.sharedMesh=kv.Value;foreach(var kv in props)kv.Key.position=kv.Value;foreach(var o in temporary)if(o)Object.DestroyImmediate(o);nav.cameraDistance=oldDistance;c.transform.position=oldCameraPosition;host.WorldRoot.SetActive(active);}}
  if(integrate)ValoriaIntegrationBuild.ValidateCurrent();else{Debug.Log("VALORIA_REFERENCE_CLEAN_WORLD_CONTACT_TRIAL_COMPLETE");EditorApplication.Exit(0);}
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}}
#endif

name: '[VALORIA] Clean reference reconstruction / native Unity'
on:
  workflow_dispatch:
  push:
    branches: [main]
    paths: ['tools/valoria-reference-clean/request.json']
permissions:
  contents: write
  actions: read
concurrency:
  group: valoria-reference-clean-native
  cancel-in-progress: false
jobs:
  native:
    if: github.ref == 'refs/heads/main' && (github.event_name == 'workflow_dispatch' || contains(github.event.head_commit.message, '[valoria-native]'))
    runs-on: [self-hosted, windows, unity-6000-3-23f1]
    timeout-minutes: 75
    outputs:
      stage: ${{ steps.native_stage.outputs.stage }}
      revision: ${{ steps.native_stage.outputs.revision }}
    defaults:
      run:
        working-directory: valoria-layered-source
    steps:
      - name: Recover installed Git
        working-directory: .
        shell: powershell
        run: |
          if(-not(Get-Command git.exe -ErrorAction SilentlyContinue)){
            $g=Get-ChildItem "$env:LOCALAPPDATA/GitHubDesktop" -Directory -Filter 'app-*' | Sort-Object Name -Descending | ForEach-Object {Join-Path $_.FullName 'resources/app/git/cmd/git.exe'} | Where-Object {Test-Path $_} | Select-Object -First 1
            if(-not $g){throw 'Installed Git unavailable'}
            Add-Content $env:GITHUB_PATH (Split-Path $g)
          }
      - uses: actions/checkout@v4
        with:
          path: valoria-layered-source
          clean: false
      - uses: actions/checkout@v4
        with:
          ref: main
          path: valoria-clean-live-main
          sparse-checkout: pipeline/active-workstreams.json
          sparse-checkout-cone-mode: false
          persist-credentials: false
      - name: Check live exclusive lease and actual native tools
        shell: powershell
        run: |
          $r=Get-Content "$env:GITHUB_WORKSPACE/valoria-clean-live-main/pipeline/active-workstreams.json" -Raw|ConvertFrom-Json
          if(@($r.active|Where-Object {$_.id -eq 'valoria-master-plan-layered-construction-20261016' -and $_.owner -eq 'chatgpt-eldoria-visual-recovery-20261020' -and $_.resources -contains 'windows-runner-heavy'}).Count -ne 1){throw 'Current clean-scene claim missing'}
          if(@($r.active|Where-Object {$_.id -ne 'valoria-master-plan-layered-construction-20261016' -and $_.resources -contains 'windows-runner-heavy'}).Count){throw 'Runner reserved by another workstream'}
          if(@(Get-Process Unity,blender -ErrorAction SilentlyContinue).Count){throw 'Shared native tools busy'}
          if(-not(Test-Path $env:UNITY_EDITOR_PATH)){throw 'Unity unavailable'}
          New-Item -ItemType Directory -Force docs/evidence/valoria-reference-clean|Out-Null
      - name: Recover only the proven Unity Editor Search-index corruption in CI
        shell: powershell
        run: |
          # Native134 ended inside UnityEditor.Search.SearchDatabase.IndexationOnStartup,
          # not in Eldoria gameplay. Search is an Editor-only convenience service,
          # never a QA or game-source authority. Preserve original preferences.
          $project=Join-Path $env:GITHUB_WORKSPACE 'valoria-layered-source/Unity'
          $settings=Join-Path $project 'UserSettings/Search.index'
          $backup=Join-Path $env:RUNNER_TEMP "eldoria-search-preferences-$env:GITHUB_RUN_ID.json"
          $created=Join-Path $env:RUNNER_TEMP "eldoria-search-created-$env:GITHUB_RUN_ID.flag"
          if(Test-Path $settings){
            Copy-Item $settings $backup -Force
            $saved=Get-Content $settings -Raw -Encoding UTF8
            try {$config=$saved | ConvertFrom-Json -ErrorAction Stop}
            catch {throw 'Existing Search.index is malformed; original preserved. Refuse silent replacement.'}
            if($config.PSObject.Properties['roots']){
              $config.roots=@()
              $config | ConvertTo-Json -Depth 32 | Set-Content $settings -Encoding UTF8
              Write-Host 'ELDORIA_CI_SEARCH_INDEX_ROOTS_DISABLED_TEMPORARILY; old preferences backed up'
            } else {
              Write-Host 'ELDORIA_CI_SEARCH_INDEX_NO_ROOTS_PROPERTY; original preferences backed up'
            }
          } else {
            # CI worktrees can lack UserSettings/Search.index: the previous workaround then did nothing.
            # Unity Search maintainer workaround for the 6.3 Editor startup indexer is roots: [].
            # Create only a temporary Editor preference, not an asset or a game setting.
            New-Item -ItemType Directory -Force (Split-Path $settings) | Out-Null
            $config=[ordered]@{
              name='Assets'; type='asset'; roots=@(); includes=@();
              excludes=@('Assets/Temp/','Assets/External/','Temp/')
              options=@{disabled=$false;types=$true;properties=$true;extended=$true;dependencies=$true}
              baseScore=999
            }
            $config | ConvertTo-Json -Depth 16 | Set-Content $settings -Encoding UTF8
            'TEMPORARY_SEARCH_INDEX_CREATED' | Set-Content $created -Encoding ASCII
            Write-Host 'ELDORIA_CI_SEARCH_INDEX_CREATED_WITH_EMPTY_ROOTS; will remove after CI'
          }
          $actual=Get-Content $settings -Raw -Encoding UTF8|ConvertFrom-Json
          if($actual.PSObject.Properties['roots'] -and @($actual.roots).Count -ne 0){throw 'Editor-only Search index roots must be empty for this CI run'}
          Write-Host "ELDORIA_CI_SEARCH_INDEX_ROOTS_COUNT $(@($actual.roots).Count)"
          $cache=Join-Path $project 'Library/Search'
          if(Test-Path $cache){
            $moved=Join-Path $env:RUNNER_TEMP "eldoria-corrupt-search-cache-$env:GITHUB_RUN_ID"
            if(Test-Path $moved){throw 'Refuse to overwrite earlier Search cache backup'}
            Move-Item -LiteralPath $cache -Destination $moved -ErrorAction Stop
            Write-Host "ELDORIA_CI_SEARCH_INDEX_CACHE_ISOLATED $moved"
          }
      - name: Read existing Android update certificate identity without changing keys
        continue-on-error: true
        shell: powershell
        run: |
          $keytool=Join-Path (Split-Path $env:UNITY_EDITOR_PATH) 'Data/PlaybackEngines/AndroidPlayer/OpenJDK/bin/keytool.exe'
          $report=@{expected_sha256='f479ca92ccfa256a991936b23d0153ffad247b352a8a5ed569457db8274443d8';package='com.eldoria.valoria.v5test';old_version_code=1;old_apk_run=38279800977;keys=@();matching_key_found=$false;private_key_exported=$false}
          if(Test-Path $keytool){
            $paths=@()
            foreach($user in @(Get-ChildItem "$env:SystemDrive/Users" -Directory -ErrorAction SilentlyContinue)){$p=Join-Path $user.FullName '.android/debug.keystore';if(Test-Path $p){$paths+=$p}}
            $p=Join-Path (Split-Path $env:UNITY_EDITOR_PATH) 'Data/PlaybackEngines/AndroidPlayer/Tools/debug.keystore';if(Test-Path $p){$paths+=$p}
            foreach($p in @($paths|Select-Object -Unique)){
              $savedPreference=$ErrorActionPreference
              try{$ErrorActionPreference='Continue';$raw=(& $keytool '-J-Duser.language=en' -list -v -keystore $p -storepass android 2>&1|Out-String)}finally{$ErrorActionPreference=$savedPreference}
              $match=[regex]::Match($raw,'SHA256:\s*([0-9A-Fa-f:]+)')
              $sha=$match.Groups[1].Value.Replace(':','').ToLowerInvariant()
              $report.keys+=@{path=$p;certificate_sha256=$sha;matches_original=($sha -eq $report.expected_sha256)}
              if($sha -eq $report.expected_sha256){$report.matching_key_found=$true}
            }
          }
          $report|ConvertTo-Json -Depth 5|Set-Content docs/evidence/valoria-reference-clean/android-existing-key-check.json -Encoding utf8
          Write-Host "Original Android signing key certificate match: $($report.matching_key_found)"
      - name: Recover exact reviewed world captures from native228
        if: contains(github.event.head_commit.message, '[world-contact-recover]')
        uses: actions/download-artifact@v4
        with:
          name: valoria-world-contact-review-39486649326
          run-id: 39486649326
          github-token: ${{ github.token }}
          path: valoria-layered-source/docs/evidence/valoria-reference-clean/world-contact222

      - name: Execute requested stage in native Unity
        id: native_stage
        shell: powershell
        run: |
          $req=Get-Content tools/valoria-reference-clean/request.json -Raw|ConvertFrom-Json
          function Test-ValoriaContentLoaderCases {
            foreach($case in @('download','cached_offline','corrupt','incompatible')){
              $env:VALORIA_CONTENT_CASE=$case
              $caseLog=Join-Path $env:RUNNER_TEMP "valoria-content-$case.log"
              $caseArgs=@('-batchmode','-force-d3d11','-buildTarget','Win64','-projectPath',"$env:GITHUB_WORKSPACE/valoria-layered-source/Unity",'-executeMethod','Eldoria.ReferenceClean.Editor.ValoriaContentBuild.ValidateLoader','-logFile',$caseLog)
              $caseProcess=Start-Process $env:UNITY_EDITOR_PATH -ArgumentList $caseArgs -PassThru
              if(-not $caseProcess.WaitForExit(240000)){& taskkill.exe /PID $caseProcess.Id /T /F|Out-Null;throw "Own content loader probe timeout $case"}
              Copy-Item $caseLog "docs/evidence/valoria-reference-clean/content-loader-$case.log"
              if($caseProcess.ExitCode -ne 0 -or -not(Select-String $caseLog -Pattern 'VALORIA_REFERENCE_CLEAN_CONTENT_LOADER_COMPLETE' -Quiet)){Get-Content $caseLog -Tail 100;throw "Content loader probe failed $case"}
            }
          }
          if(Test-Path 'tools/valoria-reference-clean/publish_content.ps1'){
            $tokens=$null;$parseErrors=$null
            $null=[System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path 'tools/valoria-reference-clean/publish_content.ps1'),[ref]$tokens,[ref]$parseErrors)
            if($parseErrors.Count){throw ($parseErrors|Out-String)}
          }
          "stage=$($req.stage)" | Out-File -FilePath $env:GITHUB_OUTPUT -Encoding utf8 -Append
          "revision=$($req.revision)" | Out-File -FilePath $env:GITHUB_OUTPUT -Encoding utf8 -Append
          $method='Eldoria.ReferenceClean.Editor.ValoriaReferenceCleanBuilder.Build'
          if($req.stage -eq 'environment_author'){
            $blender=(Get-Command blender.exe -ErrorAction SilentlyContinue).Source
            if(-not $blender){foreach($base in @('C:/Program Files/Blender Foundation',"$env:LOCALAPPDATA/Programs/Blender Foundation")){if(Test-Path $base){$blender=Get-ChildItem $base -Recurse -Filter blender.exe -File|Sort-Object FullName -Descending|Select-Object -First 1 -ExpandProperty FullName};if($blender){break}}}
            if(-not $blender){throw 'Existing Blender unavailable'}
            if($req.repair_environment){& $blender -b -t 4 --python-exit-code 1 --python tools/valoria-reference-clean/author_environment_finish.py -- --repair-last-plan}
            else{& $blender -b -t 4 --python-exit-code 1 --python tools/valoria-reference-clean/author_environment_finish.py}
            if($LASTEXITCODE){throw 'Existing local artist environment authoring failed'}
            $result='docs/evidence/valoria-reference-clean/environment-finish-result.json'
            if(-not(Test-Path $result)){throw 'Environment authoring evidence missing'}
            if(-not((Get-Content $result -Raw|ConvertFrom-Json).sources_preserved)){throw 'Environment source preservation failed'}
            return
          }
          if($req.stage -eq 'quarry_geology_author'){
            $blender=(Get-Command blender.exe -ErrorAction SilentlyContinue).Source
            if(-not $blender){foreach($base in @('C:/Program Files/Blender Foundation',"$env:LOCALAPPDATA/Programs/Blender Foundation")){if(Test-Path $base){$blender=Get-ChildItem $base -Recurse -Filter blender.exe -File|Sort-Object FullName -Descending|Select-Object -First 1 -ExpandProperty FullName};if($blender){break}}}
            if(-not $blender){throw 'Existing Blender missing'}
            & $blender -b -t 4 --python-exit-code 1 --python tools/valoria-reference-clean/author_quarry_geology_v18.py
            if($LASTEXITCODE){throw 'Quarry continuous CC0 geology author failed'}
            $proof='docs/evidence/valoria-reference-clean/quarry-geology-v18-author.json'
            if(-not(Test-Path $proof)){throw 'Quarry Blender proof missing'}
            $result=Get-Content $proof -Raw|ConvertFrom-Json
            $source='Unity/Assets/Eldoria/ArtTests/ValoriaReferenceClean/Sources/EnvironmentFinish/QuarryGeologyV18.glb'
            if(-not(Test-Path $source)){throw 'Quarry author did not output GLB'}
            if($result.new_glb_sha256 -ne (Get-FileHash $source -Algorithm SHA256).Hash.ToLowerInvariant() -or $result.art_approved){throw 'Quarry source SHA or artistic approval boundary invalid'}
            Write-Host "ELDORIA_QUARRY_GEOLOGY_V18_BLENDER_AUTHOR_SUCCESS"
            return
          }
          if($req.stage -eq 'owner_city_cliffs_author'){
            $blender=(Get-Command blender.exe -ErrorAction SilentlyContinue).Source
            if(-not $blender){foreach($base in @('C:/Program Files/Blender Foundation',"$env:LOCALAPPDATA/Programs/Blender Foundation")){if(Test-Path $base){$blender=Get-ChildItem $base -Recurse -Filter blender.exe -File|Sort-Object FullName -Descending|Select-Object -First 1 -ExpandProperty FullName};if($blender){break}}}
            if(-not $blender){throw 'Existing Blender not available for original rock edits'}
            & $blender -b -t 4 --python-exit-code 1 --python tools/valoria-reference-clean/author_owner_city_cliffs_v19.py
            if($LASTEXITCODE){throw 'Measured city rock cliff Blender authoring failed'}
            $f='Unity/Assets/Eldoria/ArtTests/ValoriaReferenceClean/Sources/OwnerCityCliffsV19.glb'
            $report='docs/evidence/valoria-reference-clean/owner-city-cliffs-v19-source.json'
            if(-not(Test-Path $f) -or -not(Test-Path $report)){throw 'Real Blender GLB and evidence both required'}
            $e=Get-Content $report -Raw|ConvertFrom-Json
            if($e.art_approved -or $e.output_sha256 -ne (Get-FileHash $f -Algorithm SHA256).Hash.ToLowerInvariant()){throw 'Original rock source output did not match SHA-256 or claimed artistic approval'}
            if($e.triangles -lt 3000 -or $e.triangles -ge 120000){throw 'Unmeasured city river cliff source geometry'}
            Write-Host "ELDORIA_OWNER_CITY_GEOLOGY_AUTHORED_SOURCE_ONLY / no ART_APPROVED"
            return
          }
          if($req.stage -eq 'connected_precinct_author'){
            $blender=(Get-Command blender.exe -ErrorAction SilentlyContinue).Source
            if(-not $blender){foreach($base in @('C:/Program Files/Blender Foundation',"$env:LOCALAPPDATA/Programs/Blender Foundation")){if(Test-Path $base){$blender=Get-ChildItem $base -Recurse -Filter blender.exe -File|Sort-Object FullName -Descending|Select-Object -First 1 -ExpandProperty FullName};if($blender){break}}}
            if(-not $blender){throw 'Existing Blender installation missing; do not substitute a generator'}
            & $blender -b -t 4 --python-exit-code 1 --python tools/valoria-reference-clean/author_connected_precinct_v16.py
            if($LASTEXITCODE){throw 'Real Blender connected precinct authoring failed; no scene integration'}
