  visible-controls-web:
    needs: native
    if: needs.native.outputs.stage == 'web_playtest'
    runs-on: ubuntu-latest
    timeout-minutes: 18
    permissions:
      contents: read
      actions: read
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 1
          sparse-checkout-cone-mode: false
          sparse-checkout: |
            /tools/valoria-reference-clean/
            /docs/evidence/valoria-reference-clean/environment-city-wide-banner-after.png
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - uses: actions/download-artifact@v4
        with:
          name: valoria-integrated-web-playtest-${{ github.run_id }}
          path: unity-raw
      - name: Prepare the existing private Site transport without changing Unity bytes
        env:
          VALORIA_REVISION: ${{ needs.native.outputs.revision }}
        run: |
          python3 tools/valoria-reference-clean/prepare_web.py unity-raw prepared-site "native$VALORIA_REVISION" "$GITHUB_SHA" "$GITHUB_RUN_ID"
          node tools/valoria-reference-clean/check-web-transport.cjs prepared-site/dist/play.js
      - name: Install existing Chromium and free FFmpeg frame extractor on temporary runner
        run: |
          npm install --prefix "$RUNNER_TEMP/valoria-web-qa" --no-save --ignore-scripts playwright@1.55.0
          "$RUNNER_TEMP/valoria-web-qa/node_modules/.bin/playwright" install --with-deps chromium
          # Playwright's bundled FFmpeg is only a recorder, not necessarily on
          # PATH for the independent video/JPEG extraction acceptance gate.
          if ! command -v ffmpeg >/dev/null 2>&1; then
            sudo apt-get update -qq && sudo apt-get install -y ffmpeg
          fi
          ffmpeg -version | head -n 1
      - name: Play the exact local build with visible controls and the normal clock
        env:
          VALORIA_WEB_ROOT: ${{ github.workspace }}/prepared-site/dist
          VALORIA_PLAYTEST_OUT: ${{ github.workspace }}/web-visible-controls-evidence
          VALORIA_SOURCE_SHA: ${{ github.sha }}
          VALORIA_PLAYTEST_TIMEOUT_SECONDS: 480
          VALORIA_WEB_LOAD_TIMEOUT_SECONDS: 180
        run: |
          NODE_PATH="$RUNNER_TEMP/valoria-web-qa/node_modules" node tools/valoria-reference-clean/playtest_web.cjs
      - name: Attach the successful browser result to the verified package
        run: |
          python3 - <<'PY'
          import json,pathlib,hashlib
          root=pathlib.Path('prepared-site')
          report=pathlib.Path('web-visible-controls-evidence/report.json')
          result=json.loads(report.read_text())
          assert result['status']=='PASS' and result['checks']['exact_save_reload']['pass']
          path=root/'unity-output-verification.json'
          proof=json.loads(path.read_text())
          proof['browser_runtime_qa']=True
          proof['browser_scope']=result['scope']
          proof['tested_manifest_sha256']=result['build']['manifest_sha256']
          proof['browser_report_sha256']=hashlib.sha256(report.read_bytes()).hexdigest()
          path.write_text(json.dumps(proof,indent=2)+'\n')
          PY
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: valoria-web-visible-controls-${{ github.run_id }}
          path: web-visible-controls-evidence/**
          if-no-files-found: warn
      - uses: actions/upload-artifact@v4
        if: success()
        with:
          name: valoria-verified-private-site-${{ github.run_id }}
          path: prepared-site/**
          if-no-files-found: error

