#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace Eldoria.ReferenceClean.Editor {
public static class ValoriaRoofJunctionFinishing {
 const string Scene="Assets/Eldoria/ArtTests/ValoriaReferenceClean/Integration/Valoria_City_World_UI.unity";
 const string Tool="Assets/Eldoria/ArtTests/ValoriaReferenceClean/Integration/Editor/ValoriaRoofJunctionFinishing.cs";
 static string Ev=>Path.GetFullPath("../docs/evidence/valoria-reference-clean/roof-junction226");
 static string Survey=>Path.GetFullPath("../docs/evidence/valoria-reference-clean/world-contact222/roof-source-survey.json.gz");
 [Serializable] public class Indices {public int[] indices;}
 [Serializable] public class Part {public string name;public Vector3[] vertices,normals;public Vector2[] uv,uv2;public Indices[] submeshes;}
 [Serializable] public class Candidate {public string source_scene_sha256,survey_sha256;public Part[] parts;}
 [Serializable] public class Acceptance {public bool accepted;public string source_scene_sha256,candidate_sha256,tool_sha256;public string[] images,hashes;}
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static string ReadGzip(string path){using(var file=File.OpenRead(path))using(var zip=new System.IO.Compression.GZipStream(file,System.IO.Compression.CompressionMode.Decompress))using(var reader=new StreamReader(zip))return reader.ReadToEnd();}
 static void Need(bool b,string s){if(!b)throw new InvalidOperationException(s);}
 static void Views(ValoriaReferenceCleanGameplay city,string prefix){
  var c=city.PlayerCamera;var pos=c.transform.position;float zoom=c.orthographicSize;
  var objects=new[]{city.BastionOne,city.BastionTwo,city.Parcels.LeftBuilt,city.Parcels.RightBuilt};var active=objects.Select(o=>o.activeSelf).ToArray();
  try{for(int state=0;state<2;state++){
   objects[0].SetActive(state==0);objects[1].SetActive(state==1);objects[2].SetActive(state==1);objects[3].SetActive(state==1);string name=state==0?"I":"II";
   c.transform.position=pos;c.orthographicSize=zoom;
   ValoriaReferenceCleanBuilder.Capture(c,Ev+"/"+prefix+"-"+name+"-landscape.png",1448,1086);
   ValoriaReferenceCleanBuilder.Capture(c,Ev+"/"+prefix+"-"+name+"-portrait.png",900,1600);
   var r=objects[state].GetComponentsInChildren<MeshRenderer>(true).Single(x=>x.name=="Bastion_"+name);
   c.transform.position=r.bounds.center-c.transform.forward*100;c.orthographicSize=11;
   ValoriaReferenceCleanBuilder.Capture(c,Ev+"/"+prefix+"-"+name+"-roof-detail.png",1448,1086);
  }}finally{c.transform.position=pos;c.orthographicSize=zoom;for(int i=0;i<objects.Length;i++)objects[i].SetActive(active[i]);}
 }
 public static void Trial(){Run(false);}
 public static void Integrate(){Run(true);}
 static void Run(bool integrate){try{
  Directory.CreateDirectory(Ev);string sourceHash=Hash(Scene);var data=JsonUtility.FromJson<Candidate>(ReadGzip(Ev+"/candidate.json.gz"));
  Need(data.source_scene_sha256==sourceHash&&data.survey_sha256==Hash(Survey),"Exact measured current architecture required");Need(data.parts.Length==2,"Both established Bastion stages required");
  var approved=new Dictionary<string,byte[]>();if(integrate){var a=JsonUtility.FromJson<Acceptance>(File.ReadAllText(Ev+"/accepted-candidate.json"));Need(a.accepted&&a.source_scene_sha256==sourceHash&&a.candidate_sha256==Hash(Ev+"/candidate.json.gz")&&a.tool_sha256==Hash(Tool),"Exact reviewed roof candidate required");Need(a.images.Length==6&&a.hashes.Length==6,"Both states, both orientations and roof detail required");for(int i=0;i<6;i++){Need(Hash(Ev+"/"+a.images[i])==a.hashes[i],"Reviewed roof image changed");approved.Add(a.images[i],File.ReadAllBytes(Ev+"/"+a.images[i]));}}
  EditorSceneManager.OpenScene(Scene,OpenSceneMode.Single);var city=Object.FindFirstObjectByType<ValoriaReferenceCleanGameplay>();var original=new Dictionary<MeshFilter,Mesh>();var owned=new List<Mesh>();bool saved=false;
  var colliders=Object.FindObjectsByType<MeshCollider>(FindObjectsInactive.Include,FindObjectsSortMode.None);var collisionMeshes=colliders.Select(c=>c.sharedMesh).ToArray();
  try{
   Views(city,"before");foreach(var part in data.parts){
    var root=part.name=="Bastion_I"?city.BastionOne:city.BastionTwo;var f=root.GetComponentsInChildren<MeshFilter>(true).Single(x=>x.name==part.name);original.Add(f,f.sharedMesh);
    Need(part.submeshes.Length==f.sharedMesh.subMeshCount&&part.submeshes.Length==f.GetComponent<Renderer>().sharedMaterials.Length,"Material identities changed");
    var m=new Mesh{name=part.name+" / seated slate and retained tower geometry",indexFormat=IndexFormat.UInt32};m.vertices=part.vertices.Select(v=>f.transform.InverseTransformPoint(v)).ToArray();m.normals=part.normals.Select(n=>f.transform.InverseTransformDirection(n).normalized).ToArray();m.uv=part.uv;if(part.uv2.Length==part.vertices.Length)m.uv2=part.uv2;m.subMeshCount=part.submeshes.Length;for(int i=0;i<m.subMeshCount;i++)m.SetTriangles(part.submeshes[i].indices,i);m.RecalculateBounds();m.RecalculateTangents();owned.Add(m);f.sharedMesh=m;
   }
   for(int i=0;i<colliders.Length;i++)Need(colliders[i].sharedMesh==collisionMeshes[i],"Architecture collision changed");Views(city,"after");Need(Hash(Scene)==sourceHash,"Trial unexpectedly saved scene");
   File.WriteAllText(Ev+"/unity-review.json","{\"same_camera_light\":true,\"both_bastion_stages\":true,\"materials_retained\":true,\"colliders_unchanged\":true,\"scene_saved\":false,\"art_approved\":false}");
   if(integrate){var differences=new List<string>();foreach(var a in approved){differences.Add(ValoriaTerrainBankAuthoring.CompareRender(a.Value,Ev+"/"+a.Key));File.WriteAllBytes(Ev+"/approved-"+a.Key,a.Value);}File.WriteAllText(Ev+"/render-identity.json","["+string.Join(",",differences)+"]");const string folder="Assets/Eldoria/ArtTests/ValoriaReferenceClean/Integration/RoofJunction226";Need(!Directory.Exists(folder),"Refuse overwrite of retained architecture");Directory.CreateDirectory(folder);AssetDatabase.Refresh();for(int i=0;i<owned.Count;i++)AssetDatabase.CreateAsset(owned[i],folder+"/Bastion-"+i+".asset");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(city.gameObject.scene);Need(EditorSceneManager.SaveScene(city.gameObject.scene,Scene),"Roof integration save failed");saved=true;File.WriteAllText(Ev+"/integrated.json","{\"scene_sha256\":\""+Hash(Scene)+"\",\"gameplay_gate\":\"PENDING_CURRENT_PROBE\",\"published\":false}");}
  }finally{if(!saved){foreach(var p in original)p.Key.sharedMesh=p.Value;foreach(var m in owned)if(m)Object.DestroyImmediate(m);}}
  if(integrate)ValoriaIntegrationBuild.ValidateCurrent();else{Debug.Log("VALORIA_ROOF_JUNCTION_TRIAL_COMPLETE");EditorApplication.Exit(0);}
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}}
#endif

roof_workflow_prepared:
name: '[VALORIA] Clean reference reconstruction / native Unity'
on:
  workflow_dispatch:
  push:
    branches: [main]
    paths: ['tools/valoria-reference-clean/request.json']
permissions:
  contents: write
  actions: read
concurrency:
  group: valoria-reference-clean-native
  cancel-in-progress: false
jobs:
  native:
    if: github.ref == 'refs/heads/main' && (github.event_name == 'workflow_dispatch' || contains(github.event.head_commit.message, '[valoria-native]'))
    runs-on: [self-hosted, windows, unity-6000-3-23f1]
    timeout-minutes: 75
    outputs:
      stage: ${{ steps.native_stage.outputs.stage }}
      revision: ${{ steps.native_stage.outputs.revision }}
    defaults:
      run:
        working-directory: valoria-layered-source
    steps:
      - name: Recover installed Git
        working-directory: .
        shell: powershell
        run: |
          if(-not(Get-Command git.exe -ErrorAction SilentlyContinue)){
            $g=Get-ChildItem "$env:LOCALAPPDATA/GitHubDesktop" -Directory -Filter 'app-*' | Sort-Object Name -Descending | ForEach-Object {Join-Path $_.FullName 'resources/app/git/cmd/git.exe'} | Where-Object {Test-Path $_} | Select-Object -First 1
            if(-not $g){throw 'Installed Git unavailable'}
            Add-Content $env:GITHUB_PATH (Split-Path $g)
          }
      - uses: actions/checkout@v4
        with:
          path: valoria-layered-source
          clean: false
      - uses: actions/checkout@v4
        with:
          ref: main
          path: valoria-clean-live-main
          sparse-checkout: pipeline/active-workstreams.json
          sparse-checkout-cone-mode: false
          persist-credentials: false
      - name: Check live exclusive lease and actual native tools
        shell: powershell
        run: |
          $r=Get-Content "$env:GITHUB_WORKSPACE/valoria-clean-live-main/pipeline/active-workstreams.json" -Raw|ConvertFrom-Json
          if(@($r.active|Where-Object {$_.id -eq 'valoria-master-plan-layered-construction-20261016' -and $_.owner -eq 'chatgpt-eldoria-visual-recovery-20261020' -and $_.resources -contains 'windows-runner-heavy'}).Count -ne 1){throw 'Current clean-scene claim missing'}
          if(@($r.active|Where-Object {$_.id -ne 'valoria-master-plan-layered-construction-20261016' -and $_.resources -contains 'windows-runner-heavy'}).Count){throw 'Runner reserved by another workstream'}
          if(@(Get-Process Unity,blender -ErrorAction SilentlyContinue).Count){throw 'Shared native tools busy'}
          if(-not(Test-Path $env:UNITY_EDITOR_PATH)){throw 'Unity unavailable'}
          New-Item -ItemType Directory -Force docs/evidence/valoria-reference-clean|Out-Null
      - name: Recover only the proven Unity Editor Search-index corruption in CI
        shell: powershell
        run: |
          # Native134 ended inside UnityEditor.Search.SearchDatabase.IndexationOnStartup,
          # not in Eldoria gameplay. Search is an Editor-only convenience service,
          # never a QA or game-source authority. Preserve original preferences.
          $project=Join-Path $env:GITHUB_WORKSPACE 'valoria-layered-source/Unity'
          $settings=Join-Path $project 'UserSettings/Search.index'
          $backup=Join-Path $env:RUNNER_TEMP "eldoria-search-preferences-$env:GITHUB_RUN_ID.json"
          $created=Join-Path $env:RUNNER_TEMP "eldoria-search-created-$env:GITHUB_RUN_ID.flag"
          if(Test-Path $settings){
            Copy-Item $settings $backup -Force
            $saved=Get-Content $settings -Raw -Encoding UTF8
            try {$config=$saved | ConvertFrom-Json -ErrorAction Stop}
            catch {throw 'Existing Search.index is malformed; original preserved. Refuse silent replacement.'}
            if($config.PSObject.Properties['roots']){
              $config.roots=@()
              $config | ConvertTo-Json -Depth 32 | Set-Content $settings -Encoding UTF8
              Write-Host 'ELDORIA_CI_SEARCH_INDEX_ROOTS_DISABLED_TEMPORARILY; old preferences backed up'
            } else {
              Write-Host 'ELDORIA_CI_SEARCH_INDEX_NO_ROOTS_PROPERTY; original preferences backed up'
            }
          } else {
            # CI worktrees can lack UserSettings/Search.index: the previous workaround then did nothing.
            # Unity Search maintainer workaround for the 6.3 Editor startup indexer is roots: [].
            # Create only a temporary Editor preference, not an asset or a game setting.
            New-Item -ItemType Directory -Force (Split-Path $settings) | Out-Null
            $config=[ordered]@{
              name='Assets'; type='asset'; roots=@(); includes=@();
              excludes=@('Assets/Temp/','Assets/External/','Temp/')
              options=@{disabled=$false;types=$true;properties=$true;extended=$true;dependencies=$true}
              baseScore=999
            }
            $config | ConvertTo-Json -Depth 16 | Set-Content $settings -Encoding UTF8
            'TEMPORARY_SEARCH_INDEX_CREATED' | Set-Content $created -Encoding ASCII
            Write-Host 'ELDORIA_CI_SEARCH_INDEX_CREATED_WITH_EMPTY_ROOTS; will remove after CI'
          }
          $actual=Get-Content $settings -Raw -Encoding UTF8|ConvertFrom-Json
          if($actual.PSObject.Properties['roots'] -and @($actual.roots).Count -ne 0){throw 'Editor-only Search index roots must be empty for this CI run'}
          Write-Host "ELDORIA_CI_SEARCH_INDEX_ROOTS_COUNT $(@($actual.roots).Count)"
          $cache=Join-Path $project 'Library/Search'
          if(Test-Path $cache){
            $moved=Join-Path $env:RUNNER_TEMP "eldoria-corrupt-search-cache-$env:GITHUB_RUN_ID"
            if(Test-Path $moved){throw 'Refuse to overwrite earlier Search cache backup'}
            Move-Item -LiteralPath $cache -Destination $moved -ErrorAction Stop
            Write-Host "ELDORIA_CI_SEARCH_INDEX_CACHE_ISOLATED $moved"
          }
      - name: Read existing Android update certificate identity without changing keys
        continue-on-error: true
        shell: powershell
        run: |
          $keytool=Join-Path (Split-Path $env:UNITY_EDITOR_PATH) 'Data/PlaybackEngines/AndroidPlayer/OpenJDK/bin/keytool.exe'
          $report=@{expected_sha256='f479ca92ccfa256a991936b23d0153ffad247b352a8a5ed569457db8274443d8';package='com.eldoria.valoria.v5test';old_version_code=1;old_apk_run=38279800977;keys=@();matching_key_found=$false;private_key_exported=$false}
          if(Test-Path $keytool){
            $paths=@()
            foreach($user in @(Get-ChildItem "$env:SystemDrive/Users" -Directory -ErrorAction SilentlyContinue)){$p=Join-Path $user.FullName '.android/debug.keystore';if(Test-Path $p){$paths+=$p}}
            $p=Join-Path (Split-Path $env:UNITY_EDITOR_PATH) 'Data/PlaybackEngines/AndroidPlayer/Tools/debug.keystore';if(Test-Path $p){$paths+=$p}
            foreach($p in @($paths|Select-Object -Unique)){
              $savedPreference=$ErrorActionPreference
              try{$ErrorActionPreference='Continue';$raw=(& $keytool '-J-Duser.language=en' -list -v -keystore $p -storepass android 2>&1|Out-String)}finally{$ErrorActionPreference=$savedPreference}
              $match=[regex]::Match($raw,'SHA256:\s*([0-9A-Fa-f:]+)')
              $sha=$match.Groups[1].Value.Replace(':','').ToLowerInvariant()
              $report.keys+=@{path=$p;certificate_sha256=$sha;matches_original=($sha -eq $report.expected_sha256)}
              if($sha -eq $report.expected_sha256){$report.matching_key_found=$true}
            }
          }
          $report|ConvertTo-Json -Depth 5|Set-Content docs/evidence/valoria-reference-clean/android-existing-key-check.json -Encoding utf8
          Write-Host "Original Android signing key certificate match: $($report.matching_key_found)"
      - name: Execute requested stage in native Unity
        id: native_stage
        shell: powershell
        run: |
          $req=Get-Content tools/valoria-reference-clean/request.json -Raw|ConvertFrom-Json
          function Test-ValoriaContentLoaderCases {
            foreach($case in @('download','cached_offline','corrupt','incompatible')){
              $env:VALORIA_CONTENT_CASE=$case
              $caseLog=Join-Path $env:RUNNER_TEMP "valoria-content-$case.log"
              $caseArgs=@('-batchmode','-force-d3d11','-buildTarget','Win64','-projectPath',"$env:GITHUB_WORKSPACE/valoria-layered-source/Unity",'-executeMethod','Eldoria.ReferenceClean.Editor.ValoriaContentBuild.ValidateLoader','-logFile',$caseLog)
              $caseProcess=Start-Process $env:UNITY_EDITOR_PATH -ArgumentList $caseArgs -PassThru
              if(-not $caseProcess.WaitForExit(240000)){& taskkill.exe /PID $caseProcess.Id /T /F|Out-Null;throw "Own content loader probe timeout $case"}
              Copy-Item $caseLog "docs/evidence/valoria-reference-clean/content-loader-$case.log"
              if($caseProcess.ExitCode -ne 0 -or -not(Select-String $caseLog -Pattern 'VALORIA_REFERENCE_CLEAN_CONTENT_LOADER_COMPLETE' -Quiet)){Get-Content $caseLog -Tail 100;throw "Content loader probe failed $case"}
            }
          }
          if(Test-Path 'tools/valoria-reference-clean/publish_content.ps1'){
            $tokens=$null;$parseErrors=$null
            $null=[System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path 'tools/valoria-reference-clean/publish_content.ps1'),[ref]$tokens,[ref]$parseErrors)
            if($parseErrors.Count){throw ($parseErrors|Out-String)}
          }
          "stage=$($req.stage)" | Out-File -FilePath $env:GITHUB_OUTPUT -Encoding utf8 -Append
          "revision=$($req.revision)" | Out-File -FilePath $env:GITHUB_OUTPUT -Encoding utf8 -Append
          $method='Eldoria.ReferenceClean.Editor.ValoriaReferenceCleanBuilder.Build'
          if($req.stage -eq 'environment_author'){
            $blender=(Get-Command blender.exe -ErrorAction SilentlyContinue).Source
            if(-not $blender){foreach($base in @('C:/Program Files/Blender Foundation',"$env:LOCALAPPDATA/Programs/Blender Foundation")){if(Test-Path $base){$blender=Get-ChildItem $base -Recurse -Filter blender.exe -File|Sort-Object FullName -Descending|Select-Object -First 1 -ExpandProperty FullName};if($blender){break}}}
            if(-not $blender){throw 'Existing Blender unavailable'}
            if($req.repair_environment){& $blender -b -t 4 --python-exit-code 1 --python tools/valoria-reference-clean/author_environment_finish.py -- --repair-last-plan}
            else{& $blender -b -t 4 --python-exit-code 1 --python tools/valoria-reference-clean/author_environment_finish.py}
            if($LASTEXITCODE){throw 'Existing local artist environment authoring failed'}
            $result='docs/evidence/valoria-reference-clean/environment-finish-result.json'
            if(-not(Test-Path $result)){throw 'Environment authoring evidence missing'}
            if(-not((Get-Content $result -Raw|ConvertFrom-Json).sources_preserved)){throw 'Environment source preservation failed'}
            return
